template:
@php
    // The date and the time are a wall clock of the site's time zone; a moment nobody can read is none.
    $day = substr(is_string($date) ? trim($date) : '', 0, 10);
    $clock = is_string($time) && preg_match('/^\d{1,2}:\d{2}(:\d{2})?$/', trim($time)) === 1 ? trim($time) : '00:00';
    $moment = null;
    if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $day) === 1 && checkdate((int) substr($day, 5, 2), (int) substr($day, 8, 2), (int) substr($day, 0, 4))) {
        try {
            $moment = \WebxUi\Widgets\View\Components\Countdown::moment($day.' '.$clock);
        } catch (\Throwable) {
            $moment = null;
        }
    }
    // "Hide the block", or nothing written to say: when it ends, the block goes.
    $message = $end !== 'hide' && $ended ? wx_text($ended)->plain() : '';
    $message = trim($message) !== '' ? $message : null;
@endphp
@if ($moment && ($message !== null || $moment->isFuture()))
<section class="b-countdown" data-wx-block="countdown" data-webx-countdown-scope>
    @if ($heading)
        <h2 class="b-countdown__heading">{{ $heading }}</h2>
    @endif
    @if ($text)
        <p class="b-countdown__text">{{ $text }}</p>
    @endif
    <x-webx-countdown class="b-countdown__timer" :to="$moment" :ended="$message" />
</section>
@endif

styles:
.b-countdown {
    container-type: inline-size;
    text-align: center;
    --webx-countdown-justify: center;
}

.b-countdown__heading {
    margin: 0 0 0.5em;
}

.b-countdown__text {
    margin: 0 auto 1.25em;
    max-width: 40em;
    opacity: 0.8;
}

.b-countdown__timer {
    margin: 0 auto;
}
